INSERT INTO `products` (`id`, `title`, `slug`, `brand_id`, `category_id`, `seller_id`, `description`, `highlights`, `specifications`, `warranty`, `return_policy`, `base_mrp`, `base_price`, `is_featured`, `is_active`, `status`, `rating`, `review_count`) VALUES
(1, 'Celvas Back Cover for Apple iPhone 15', 'celvas-back-cover-apple-iphone-15', 1, 15, 1, 'Engineered with aerospace-grade polycarbonate and impact-absorbing TPU shock bumpers, the Celvas Armor Case for Apple iPhone 15 offers military-grade drop protection up to 10 feet. It features raised 1.5mm bezels to shield your Super Retina XDR display and advanced camera lens cluster from scratches. With a matte oleophobic finish that resists fingerprints and yellowing, and built-in MagSafe magnetic ring array for ultra-fast wireless charging, this is the ultimate case for your iPhone 15.', '[\"Compatible with Apple iPhone 15 (6.1 inch)\",\"Built-in MagSafe Strong Magnetic Ring Array for Qi2 Wireless Charging\",\"Certified Military Grade Drop Protection (MIL-STD-810G)\",\"1.5mm Raised Camera Lip & 1.2mm Raised Screen Edges\",\"Anti-Fingerprint Matte Frosted Translucent Finish with tactile clicky alloy buttons\"]', '{\"Brand\":\"Celvas\",\"Model Name\":\"MagArmor Stealth Shield\",\"Color\":\"Matte Midnight Black\",\"Material\":\"Polycarbonate Backplate + Shockproof TPU Bumper\",\"Type\":\"Back Cover with MagSafe\",\"Drop Protection\":\"10 Feet Certified Drop Tested\",\"Wireless Charging\":\"Full MagSafe & Qi Compatibility\",\"Package Contents\":\"1x Celvas Armor Case, 1x Screen Cleaning Wipe Kit\"}', '1 Year Warranty', '7 Days Replacement', 1499, 499, 1, 1, 'APPROVED', 4.65, 384),
(2, 'Apple iPhone 15 (128 GB) - Black', 'apple-iphone-15-128-gb---black-2', 2, 14, 2, 'Experience premium quality with Apple iPhone 15 (128 GB) - Black. Designed with superior craftsmanship, durable materials and high performance for long-lasting everyday satisfaction.', '[\"Top rated genuine product with verified brand warranty\",\"Fast doorstep delivery across all India pincodes\",\"7 Days easy return and replacement guarantee\",\"Special bank offers and cashback eligible\"]', '{\"Brand\":\"Verified Official Brand\",\"Model\":\"Apple iPhone 15 (128 GB) - Black\",\"Warranty\":\"1 Year Manufacturer Warranty\",\"Country of Origin\":\"India\"}', '1 Year Warranty', '7 Days Replacement', 79900, 69999, 1, 1, 'APPROVED', 4.8, 2456),
